"""Main entry point for PylonChess"""

import os
import time
import traceback

from pylonchess.gui import ChessGUI

_CRASH_LOG = os.path.expanduser("~/.pylonchess_crash.log")


def main():
    """Run the chess game. Any unexpected error is written to a log file so a
    launch failure can be diagnosed even when no terminal is visible."""
    try:
        game = ChessGUI()
        game.run()
    except SystemExit:
        raise
    except Exception:
        try:
            with open(_CRASH_LOG, "a") as fh:
                fh.write("\n--- crash at %s ---\n" % time.strftime("%Y-%m-%d %H:%M:%S"))
                traceback.print_exc(file=fh)
        except Exception:
            pass
        raise


if __name__ == "__main__":
    main()